    private void assertAccountRejected(Consumer<Account> change) {
        Account account = new Account();
        change.accept(account);

        int users = db.getUsers().size();
        int contacts = db.getContacts().size();
        int locations = db.getLocations().size();

        boolean created = assertDoesNotThrow(() -> submit(account));

        assertFalse(created, "account must be rejected");
        assertEquals(users, db.getUsers().size());
        assertEquals(contacts, db.getContacts().size());
        assertEquals(locations, db.getLocations().size());
    }

    private void assertAccountAccepted(Consumer<Account> change) {
        Account account = new Account();
        change.accept(account);

        int users = db.getUsers().size();
        int contacts = db.getContacts().size();
        int locations = db.getLocations().size();

        boolean created = assertDoesNotThrow(() -> submit(account));

        assertTrue(created, "account must be created");
        assertEquals(users + 1, db.getUsers().size());
        assertEquals(contacts + 2, db.getContacts().size());
        assertEquals(locations + 1, db.getLocations().size());

        db.read();
        assertNotNull(db.attemptLogin("jsmith@outlook.com", account.password),
                "the new account must have been saved to the data files");
    }

    private DynamicTest rejected(String label, Consumer<Account> change) {
        return dynamicTest("rejected: " + label, () -> {
            resetState();
            assertAccountRejected(change);
        });
    }

    private DynamicTest accepted(String label, Consumer<Account> change) {
        return dynamicTest("accepted: " + label, () -> {
            resetState();
            assertAccountAccepted(change);
        });
    }

