    private static final class UuidSubject<T extends Serializable> {
        final String method;
        final Class<T> cls;
        final Function<UUID, T> getter;

        UuidSubject(String method, Class<T> cls, Function<UUID, T> getter) {
            this.method = method;
            this.cls = cls;
            this.getter = getter;
        }
    }

    private static <T extends Serializable> T first(DataList<T> list) {
        assumeFalse(list.getAll().isEmpty(), "sample data has no such objects");
        return list.getAll().get(0);
    }

    @SuppressWarnings("unchecked")
    private <T extends Serializable> DynamicNode uuidTests(
            UuidSubject<T> subject) {

        DataList<T> list = (DataList<T>) db.get(subject.cls);

        return dynamicContainer(subject.method, List.of(
                dynamicTest("object in list with UUID in table", () -> {
                    resetState();
                    T object = first(list);

                    assertSame(object, subject.getter.apply(object.getId()));
                }),
                dynamicTest("object in list without UUID in table", () -> {
                    resetState();
                    T object = first(list);
                    list.remove(object);
                    list.getAll().add(object);

                    assertSame(object, subject.getter.apply(object.getId()));
                }),
                dynamicTest("object not in list but with UUID in table", () -> {
                    resetState();
                    T object = first(list);
                    list.getAll().remove(object);

                    assertNull(subject.getter.apply(object.getId()));
                }),
                dynamicTest("object not in list and without UUID in table", () -> {
                    resetState();
                    T object = first(list);
                    list.remove(object);

                    assertNull(subject.getter.apply(object.getId()));
                }),
                dynamicTest("object is null", () -> {
                    resetState();
                    list.getAll().add(null);

                    T found = assertDoesNotThrow(
                            () -> subject.getter.apply(UUID.randomUUID()));

                    assertNull(found);
                    list.getAll().removeIf(Objects::isNull);
                }),
                dynamicTest("UUID is null", () -> {
                    resetState();

                    T found = assertDoesNotThrow(
                            () -> subject.getter.apply(null));

                    assertNull(found);
                })));
    }

    /**
     * +----------------------------------------------+---------------------------------------------------------------+
     * | test                                         | reasoning                                                     |
     * +----------------------------------------------+---------------------------------------------------------------+
     * | object in list with UUID in table            | standard                                                      |
     * | object in list without UUID in table         | should search object list after UUID table has been exhausted |
     * | object not in list but with UUID in table    | should return null                                            |
     * | object not in list and without UUID in table | should return null                                            |
     * | object is null                               | null check                                                    |
     * | UUID is null                                 | null check                                                    |
     * +----------------------------------------------+---------------------------------------------------------------+
     */
    @TestFactory
    @DisplayName("get*ByUUID")
    Stream<DynamicNode> getByUUID() {
        List<UuidSubject<?>> subjects = List.of(
                new UuidSubject<LivingBeing>("getLivingBeingByUUID", LivingBeing.class,
                        db::getLivingBeingByUUID),
                new UuidSubject<User>("getUserByUUID", User.class,
                        db::getUserByUUID),
                new UuidSubject<Volunteer>("getVolunteerByUUID", Volunteer.class,
                        db::getVolunteerByUUID),
                new UuidSubject<ReliefRequest>("getReliefRequestByUUID",
                        ReliefRequest.class, db::getReliefRequestByUUID),
                new UuidSubject<Shelter>("getShelterByUUID", Shelter.class,
                        db::getShelterByUUID),
                new UuidSubject<Contact>("getContactByUUID", Contact.class,
                        db::getContactByUUID),
                new UuidSubject<Location>("getLocationByUUID", Location.class,
                        db::getLocationByUUID));

        List<DynamicNode> nodes = new ArrayList<>();

        for (UuidSubject<?> subject : subjects) {
            nodes.add(uuidTests(subject));
        }

        return nodes.stream();
    }

    // ------------------------------------------------------------------
    // get
    // ------------------------------------------------------------------

    /**
     * +----------------------+-----------------------+
     * | test                 | reasoning             |
     * +----------------------+-----------------------+
     * | User.class           | standard              |
     * | ReliefRequest.class  | standard              |
     * | Hurricane.class      | standard              |
     * | Shelter.class        | standard              |
     * | Contact.class        | standard              |
     * | Location.class       | standard              |
     * | LivingBeing.class    | standard              |
     * | Volunteer.class      | standard              |
     * | ShelterManager.class | standard              |
     * | String.class         | object not in key set |
     * | null                 | null check            |
     * +----------------------+-----------------------+
     */
    @TestFactory
    @DisplayName("get(Class)")
    @SuppressWarnings({"unchecked", "rawtypes"})
    Stream<DynamicTest> get() {
        List<DynamicTest> tests = new ArrayList<>();

        for (Class<? extends Serializable> cls : MODEL_CLASSES) {
            tests.add(dynamicTest(cls.getSimpleName() + ".class", () -> {
                DataList<? extends Serializable> list = db.get(cls);

                assertNotNull(list);
                assertSame(DataList.getInstance(cls), list);
            }));
        }

        Class notSerializable = String.class;

        tests.add(dynamicTest("String.class",
                () -> assertNull(db.get(notSerializable))));
        tests.add(dynamicTest("null", () -> assertNull(db.get(null))));

        return tests.stream();
    }

    // ------------------------------------------------------------------
    // getSortedReliefRequests
    // ------------------------------------------------------------------

    private Volunteer rosaVolunteer() {
        for (Serializable object : db.get(Volunteer.class).getAll()) {
            Volunteer volunteer = (Volunteer) object;

            if (volunteer.getUserContact() != null && ROSA_EMAIL
                    .equals(volunteer.getUserContact().getEmail())) {
                return volunteer;
            }
        }

        assumeTrue(false, "sample data must contain Rosa Delgado as a volunteer");
        return null;
    }

    /**
     * +----------------------------+------------+
     * | test                       | reasoning  |
     * +----------------------------+------------+
     * | new SkillSort(rosaDelgado) | standard   |
     * | new SkillSort(null)        | null check |
     * | null                       | null check |
     * +----------------------------+------------+
     */
    @Test
    @DisplayName("getSortedReliefRequests: new SkillSort(rosaDelgado)")
    @SuppressWarnings({"unchecked", "rawtypes"})
    void getSortedReliefRequests_skillSort() {
        PriorityFilter<ReliefRequest> filter = skillSort(rosaVolunteer());
        HashSet<ReliefRequest> expected = new HashSet<>(db.getRequests());

        ArrayList<ReliefRequest> sorted = assertDoesNotThrow(
                () -> db.getSortedReliefRequests(filter));

        assertNotNull(sorted);
        assertEquals(expected, new HashSet<>(sorted),
                "sorting must keep exactly the same requests");

        for (int i = 1; i < sorted.size(); i++) {
            Object previous = filter.filter(sorted.get(i - 1));
            Object current = filter.filter(sorted.get(i));

            assertTrue(((Comparable) previous).compareTo(current) >= 0,
                    "requests must be ordered from highest to lowest priority");
        }
    }

    @Test
    @DisplayName("getSortedReliefRequests: new SkillSort(null)")
    void getSortedReliefRequests_skillSortOfNull() {
        assertDoesNotThrow(
                () -> db.getSortedReliefRequests(skillSort(null)));
    }

    @Test
    @DisplayName("getSortedReliefRequests: null")
    void getSortedReliefRequests_nullFilter() {
        assertDoesNotThrow(() -> db.getSortedReliefRequests(null));
    }
